To(__DIR__ . '/../../../', null, true); } catch (\Exception $e) { $message = $e->getMessage(); $success = false; http_response_code(500); $this->restoreMaintenanceMode(); } if (file_exists(self::TEMP_DIR . 'update.tar.gz')) { unlink(self::TEMP_DIR . 'update.tar.gz'); } if (file_exists(self::TEMP_DIR . 'update.tar')) { unlink(self::TEMP_DIR . 'update.tar'); } if (!empty($message)) { $this->saveLog($message); } $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => [ 'success' => $success, 'data' => json_encode($message, JSON_UNESCAPED_UNICODE) ] ]); break; case 4: $success = true; $message = ''; $this->restoreMaintenanceMode(); $configFile = self::DATA_DIR . 'config.json'; $autoUpdateHtaccess = false; if (file_exists($configFile)) { $config = json_decode(file_get_contents($configFile), true); if (json_last_error() === JSON_ERROR_NONE && isset($config['config']['autoUpdateHtaccess'])) { $autoUpdateHtaccess = (bool)$config['config']['autoUpdateHtaccess']; } } if ($autoUpdateHtaccess) { $success = copy('.htaccess.bak', '.htaccess'); if ($success === false) { $message = Helper::translate("La copie de sauvegarde du fichier htaccess n'a pas été restaurée !"); http_response_code(500); } unlink('.htaccess.bak'); } else { if (file_exists(self::DATA_DIR . '.rewrite')) { $fileContent = file_get_contents('.htaccess'); $rewriteData = PHP_EOL . '# URL rewriting' . PHP_EOL . '<IfModule mod_rewrite.c>' . PHP_EOL . "\tRewriteEngine on" . PHP_EOL . "\tRewriteBase " . Helper::baseUrl(false, false) . PHP_EOL . "\tRewriteCond %{REQUEST_FILENAME} !-f" . PHP_EOL . "\tRewriteCond %{REQUEST_FILENAME} !-d" . PHP_EOL . "\tRewriteRule ^(.*)\$ index.php?\$1 [L]" . PHP_EOL . '</IfModule>' . PHP_EOL . '# URL rewriting' . PHP_EOL; $fileContent = str_replace('# URL rewriting', $rewriteData, $fileContent); $success = $this->secure_file_put_contents( '.htaccess', $fileContent ); unlink(self::DATA_DIR . '.rewrite'); } } require_once ('core/module/install/resource/defaultdata.php'); $installedLanguages = $this->getData(['language']); $defaultLanguages = \init::$defaultData['language']; foreach ($installedLanguages as $key => $value) { if ( isset($value['date']) && isset($value['version']) && isset($defaultLanguages[$key]['date']) && $defaultLanguages[$key]['date'] > $value['date'] && isset($defaultLanguages[$key]['version']) && $defaultLanguages[$key]['version'] >= $value['version'] ) { copy('core/module/install/resource/i18n/' . $key . '.json', self::I18N_DIR . $key . '.json'); $this->setData(['language', $key, $defaultLanguages[$key]]); } } if (!empty($message)) { $this->saveLog($message); } $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => [ 'success' => $success, 'data' => json_encode($message, JSON_UNESCAPED_UNICODE) ] ]); } } public function update() { if ( $this->getUser('permission', __CLASS__, __FUNCTION__) !== true ) { $this->addOutput([ 'access' => false ]); } else { self::$newVersion = Helper::getUrlContents(Core::ZWII_UPDATE_URL . Core::ZWII_UPDATE_CHANNEL . '/version'); if (Helper::checkNewVersion(Core::ZWII_UPDATE_CHANNEL)) { self::$updateButtonText = Helper::translate('Mise à jour'); } $this->addOutput([ 'display' => self::DISPLAY_LAYOUT_LIGHT, 'title' => Helper::translate(self::$updateButtonText), 'view' => 'update' ]); } } private function cleanObsoleteCoreFiles(\PharData $tar): void { $pharBasePath = 'phar://' . realpath(self::TEMP_DIR . 'update.tar') . '/'; $newCoreFiles = []; foreach (new \RecursiveIteratorIterator($tar) as $file) { if ($file->isFile()) { $relativePath = substr($file->getPathname(), strlen($pharBasePath)); if (strpos($relativePath, 'core/') === 0) { $newCoreFiles[$relativePath] = true; } } } $rootDir = realpath(__DIR__ . '/../../../') . '/'; $coreIterator = new \RecursiveIteratorIterator( new \RecursiveDirectoryIterator($rootDir . 'core', \FilesystemIterator::SKIP_DOTS), \RecursiveIteratorIterator::CHILD_FIRST ); foreach ($coreIterator as $item) { $relativePath = substr($item->getRealPath(), strlen($rootDir)); if ($item->isFile()) { if (!isset($newCoreFiles[$relativePath])) { unlink($item->getRealPath()); } } elseif ($item->isDir()) { if (empty(array_diff(scandir($item->getRealPath()), ['.', '..']))) { rmdir($item->getRealPath()); } } } } private function enableMaintenanceMode(): void { if ($this->getData(['config', 'maintenance']) === true) { touch(self::DATA_DIR . '.maintenance'); } $this->setData(['config', 'maintenance', true]); usleep(500000); } private function restoreMaintenanceMode(): void { $configFile = self::DATA_DIR . 'config.json'; if (file_exists($configFile)) { $config = json_decode(file_get_contents($configFile), true); if (json_last_error() === JSON_ERROR_NONE) { $config['config']['maintenance'] = file_exists(self::DATA_DIR . '.maintenance'); file_put_contents( $configFile, json_encode($config, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ); } } if (file_exists(self::DATA_DIR . '.maintenance')) { unlink(self::DATA_DIR . '.maintenance'); } } }
